Algorithm MoneyBox
  Define price As Integer;
  Read price;
  Define day As Integer <- 1;
  Define savedToday As Integer <- 2;
  Define savings As Integer <- 2;
  While savings < price Do
    day <- day + 1;
    savedToday <- savedToday + 1;
    savings <- savings + savedToday;
  EndWhile
  Write "Day ", day, " with ", savings, " coins";
EndAlgorithm

